CREATE OR REPLACE FUNCTION public.complete_order_and_release(p_order_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_order public.orders%ROWTYPE; v_wallet public.wallet_accounts%ROWTYPE; v_transaction public.transactions%ROWTYPE; v_amount NUMERIC(12,2); BEGIN SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found: %',p_order_id; END IF; IF v_order.status='completed' THEN RETURN jsonb_build_object('success',true,'duplicate',true,'order_id',p_order_id); END IF; IF v_order.status<>'delivered' THEN RAISE EXCEPTION 'Only delivered orders can be completed'; END IF; SELECT * INTO v_wallet FROM public.wallet_accounts WHERE user_id=v_order.seller_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Seller wallet not found: %',v_order.seller_id; END IF; SELECT * INTO v_transaction FROM public.transactions WHERE reference_id=p_order_id AND user_id=v_order.seller_id AND type='earning' AND status='pending' ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No pending seller earning found for order: %',p_order_id; END IF; v_amount:=ROUND(v_transaction.amount,2); IF v_amount<=0 OR v_wallet.pending_balance<v_amount THEN RAISE EXCEPTION 'Invalid pending seller balance for order: %',p_order_id; END IF; UPDATE public.wallet_accounts SET pending_balance=pending_balance-v_amount,available_balance=available_balance+v_amount,updated_at=now() WHERE user_id=v_order.seller_id; UPDATE public.transactions SET status='completed',description='Completed earning from order '||p_order_id||' — released from pending balance' WHERE id=v_transaction.id; INSERT INTO public.wallet_ledger(user_id,order_id,transaction_id,entry_type,bucket,amount,currency,external_reference,description) VALUES(v_order.seller_id,p_order_id,v_transaction.id,'seller_release','available',v_amount,'usd','order_release:'||p_order_id,'Seller earning released from pending balance') ON CONFLICT(external_reference) DO NOTHING; UPDATE public.orders SET status='completed',completed_at=COALESCE(completed_at,now()),updated_at=now() WHERE id=p_order_id; RETURN jsonb_build_object('success',true,'duplicate',false,'order_id',p_order_id,'seller_id',v_order.seller_id,'released_amount',v_amount); END; $$;
REVOKE EXECUTE ON FUNCTION public.complete_order_and_release(UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_order_and_release(UUID) TO service_role;
CREATE OR REPLACE FUNCTION public.record_refund_accounting(p_order_id UUID,p_refund_id TEXT,p_payment_intent_id TEXT,p_refund_amount NUMERIC(12,2),p_currency TEXT DEFAULT 'usd') RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_order public.orders%ROWTYPE; v_wallet public.wallet_accounts%ROWTYPE; v_seller_transaction public.transactions%ROWTYPE; v_seller_refund NUMERIC(12,2); v_existing UUID; v_bucket TEXT; BEGIN IF lower(p_currency)<>'usd' THEN RAISE EXCEPTION 'Unsupported currency: %',p_currency; END IF; IF p_refund_amount<=0 THEN RAISE EXCEPTION 'Refund amount must be greater than zero'; END IF; SELECT id INTO v_existing FROM public.wallet_ledger WHERE external_reference='refund:'||p_refund_id; IF v_existing IS NOT NULL THEN RETURN jsonb_build_object('success',true,'duplicate',true,'order_id',p_order_id); END IF; SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found: %',p_order_id; END IF; IF ROUND(v_order.price,2)<>ROUND(p_refund_amount,2) THEN RAISE EXCEPTION 'Only full refunds are supported. Order price: %, refund: %',v_order.price,p_refund_amount; END IF; SELECT * INTO v_wallet FROM public.wallet_accounts WHERE user_id=v_order.seller_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Seller wallet not found: %',v_order.seller_id; END IF; SELECT * INTO v_seller_transaction FROM public.transactions WHERE reference_id=p_order_id AND user_id=v_order.seller_id AND type='earning' ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Seller earning not found for order: %',p_order_id; END IF; v_seller_refund:=ROUND(v_order.price*0.80,2); IF v_seller_transaction.status='pending' THEN IF v_wallet.pending_balance<v_seller_refund THEN RAISE EXCEPTION 'Insufficient seller pending balance for refund'; END IF; v_bucket:='pending'; UPDATE public.wallet_accounts SET pending_balance=pending_balance-v_seller_refund,updated_at=now() WHERE user_id=v_order.seller_id; ELSIF v_seller_transaction.status='completed' THEN IF v_wallet.available_balance<v_seller_refund THEN RAISE EXCEPTION 'Insufficient seller available balance for refund'; END IF; v_bucket:='available'; UPDATE public.wallet_accounts SET available_balance=available_balance-v_seller_refund,updated_at=now() WHERE user_id=v_order.seller_id; ELSE RAISE EXCEPTION 'Seller earning is not refundable'; END IF; INSERT INTO public.transactions(user_id,type,amount,status,reference_id,description,stripe_refund_id,stripe_payment_intent_id,currency) VALUES(v_order.buyer_id,'refund',p_refund_amount,'completed',p_order_id,'Refund for order '||p_order_id,p_refund_id,p_payment_intent_id,'usd'),(v_order.seller_id,'refund',-v_seller_refund,'completed',p_order_id,'Earning reversed for refunded order '||p_order_id,p_refund_id,p_payment_intent_id,'usd'); INSERT INTO public.wallet_ledger(user_id,order_id,entry_type,bucket,amount,currency,external_reference,description) VALUES(v_order.seller_id,p_order_id,'refund',v_bucket,-v_seller_refund,'usd','refund:'||p_refund_id,'Seller earning reversed for refund '||p_refund_id); UPDATE public.orders SET status='cancelled',refunded_at=COALESCE(refunded_at,now()),stripe_refund_id=p_refund_id,updated_at=now() WHERE id=p_order_id; RETURN jsonb_build_object('success',true,'duplicate',false,'order_id',p_order_id,'refund_amount',p_refund_amount,'seller_reversed',v_seller_refund); END; $$;
REVOKE EXECUTE ON FUNCTION public.record_refund_accounting(UUID,TEXT,TEXT,NUMERIC,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_refund_accounting(UUID,TEXT,TEXT,NUMERIC,TEXT) TO service_role;